import{_ as t,l as c,o as a,c as n,v as o,p as l,x as r,d as p,i,S as d}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"copy_from_user","description":"","frontmatter":{"title":"copy_from_user","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/copy-from-user.md","filePath":"cs/copy-from-user.md","lastUpdated":1789023840000}'),_={name:"cs/copy-from-user.md"};function m(u,e,h,f,E,A){const s=c("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="copy-from-user" tabindex="-1">copy_from_user <a class="header-anchor" href="#copy-from-user" aria-label="Permalink to &quot;copy_from_user&quot;">​</a></h1><div class="epigraph"><p>内核绝不能信任用户指针一直指向合法、稳定的用户页；要把入参拷进内核缓冲区再解析。</p><footer>—— 据 Love, Linux Kernel Development；Tanenbaum and Bos, MOS 整理</footer></div><p><a href="/cs/syscall-path">上一课</a>给出自愿陷入的分发：按号跳到实现，并点过「从用户地址空间拷贝入参」。缺口是把那句纪律做成机制：用户指针可能缺页、可能指向内核映射、可能在拷贝途中被另一线程 <code>unmap</code>。<a href="/cs/paging-vm">分页</a>下内核若直接解引用用户地址，轻则读到错误数据，重则破坏内核不变量。本课只钉 <strong>copy_from_user / copy_to_user</strong>，不写利用技巧。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ABI 只把指针值放进寄存器。实现若当内核指针用，用户可以把地址指到内核代码或另一进程的页（在共享映射下）。即使地址落在用户范围，页也可能尚未安住，需要走缺页。缺口不是新的系统调用号，而是：<strong>校验范围 → 用可故障的拷贝例程搬字节 → 失败则返回错误，不让内核 oops 成崩溃</strong>。</p><p>本课不把每个架构的 <code>access_ok</code> 实现写成清单。</p><p><span class="marginnote">拷贝过程允许睡眠（补页）。因此它不能在硬中断上半部里做。上半部与用户缓冲区的会合，仍走下半部与等待队列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核准备自己的栈上或堆上缓冲区。<code>copy_from_user</code>：检查地址落在用户空间，按页搬入，遇缺页则就地处理或失败。字符串还要有上限，避免无界扫描。写出时用 <code>copy_to_user</code>，同样不能假设用户页可写一直成立。完成后内核只解析<strong>自己的副本</strong>；用户之后改原页不影响这次调用。</p>',9)),(a(),l(d,null,{default:r(()=>[i(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PTR%5B%22%E7%94%A8%E6%88%B7%E6%8C%87%E9%92%88%22%5D%20--%3E%20CHK%5B%22%E8%8C%83%E5%9B%B4%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20CHK%20--%3E%20CPY%5B%22%E5%8F%AF%E6%95%85%E9%9A%9C%E6%8B%B7%E8%B4%9D%E8%BF%9B%E5%86%85%E6%A0%B8%E7%BC%93%E5%86%B2%22%5D%0A%20%20CPY%20--%3E%20IMPL%5B%22%E5%8F%AA%E8%A7%A3%E6%9E%90%E5%89%AF%E6%9C%AC%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>返回值长度、部分拷贝失败，由各调用自己定义；本课只要求失败可见，不把内核状态写到一半当成功。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>拷贝把<a href="/cs/kernel-user">内核与用户态</a>的不对称变成操作：用户页对内核「可见」不等于「可当内核对象用」。副本切断了用户并发修改与内核解析之间的数据竞争——至少对这一次入参如此。写出副本则防止内核把内核地址当用户缓冲区交给硬件 DMA；DMA 路径更后，本课只预告：设备地址也不能是未校验的用户指针。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讨论如何探测内核布局，不给越界读写的构造。也不把 <code>get_user</code> 的单字段快路径写成与块拷贝对立的另一哲学：对象仍是安全搬迁。 seccomp 与能力模型是安全课。</p><p>后课默认：系统调用的变长入参先拷进内核。阻塞调用在睡眠中被信号打断后，这次拷贝与这次调用要不要重来，下一课讲重启系统调用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>用户指针不可直接解引用；拷进内核缓冲再解析。</li><li>拷贝可缺页、可失败；不能在硬 IRQ 上半部里做。</li><li>信号打断慢调用是下一课缺口。</li><li>出处：Love, <em>LKD</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',8))])}const C=t(_,[["render",m]]);export{T as __pageData,C as default};
